INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine vollständige Datensicherung immer die schnellste Methode ist?', 2, '[{"text": "Nein", "correct": true, "because": "Inkrementelle Sicherungen sind schneller"}, {"text": "Ja", "correct": false, "because": "Vollständige Sicherung dauert länger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode sichert nur geänderte Daten seit der letzten Sicherung?', 3, '[{"text": "Inkrementelle Sicherung", "correct": true, "because": "Speichert nur Änderungen"}, {"text": "Vollständige Sicherung", "correct": false, "because": "Sichert alles"}, {"text": "Spiegelung", "correct": false, "because": "Kopiert in Echtzeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken gehören zur Datensicherung?', 5, '[{"text": "Vollständige Sicherung", "correct": true, "because": "Kopiert alle Daten"}, {"text": "Differenzielle Sicherung", "correct": true, "because": "Sichert Änderungen seit Vollbackup"}, {"text": "Inkrementelle Sicherung", "correct": true, "because": "Spart Speicherplatz"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Sicherungsfaktor"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein RAID-System ist eine Datensicherung. b) Es schützt vor Hardwarefehlern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, RAID kein Backup"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer Datensicherung?', 4, '[{"text": "Speicherort", "correct": false, "because": "Sichert Verfügbarkeit"}, {"text": "Häufigkeit", "correct": false, "because": "Bestimmt Aktualität"}, {"text": "Verpackungsdesign", "correct": true, "because": "Kein Sicherungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine inkrementelle Sicherung die Wiederherstellung verlangsamt?', 2, '[{"text": "Ja", "correct": true, "because": "Mehrere Schritte nötig"}, {"text": "Nein", "correct": false, "because": "Komplexere Wiederherstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode schützt physische Server vor Diebstahl?', 4, '[{"text": "Zutrittskontrollen", "correct": true, "because": "Begrenzen Zugang"}, {"text": "Software-Updates", "correct": false, "because": "Für digitale Sicherheit"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Cloud-Backups immer unsicher sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Sicher mit Verschlüsselung"}, {"text": "Ja", "correct": false, "because": "Sicherheit abhängig von Anbieter"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein RAID-1 ein vollständiges Backup?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Spiegelung, kein Backup"}, {"text": "Ja", "correct": false, "because": "Schützt nur vor Ausfall"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherungsmethoden sind für Daten typisch?', 5, '[{"text": "Vollbackup", "correct": true, "because": "Sichert alles"}, {"text": "Cloud-Backup", "correct": true, "because": "Externer Speicher"}, {"text": "Tape-Backup", "correct": true, "because": "Langfristige Archivierung"}, {"text": "Bildschirmschoner", "correct": false, "because": "Kein Sicherungsfaktor"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Datensicherung?', 4, '[{"text": "Sicherer Speicherort", "correct": true, "because": "Schützt vor Verlust"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Differenzielle Sicherung speichert Änderungen seit Vollbackup. b) Sie ist schneller als inkrementelle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, inkrementelle oft schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine effektive Datensicherung?', 3, '[{"text": "Speichermedium", "correct": false, "because": "Speichert Daten"}, {"text": "Verschlüsselung", "correct": false, "because": "Schützt Inhalt"}, {"text": "Dekoratives Etikett", "correct": true, "because": "Kein Sicherungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Daten vor physischem Schaden sichere?', 4, '[{"text": "Offsite-Backup und Zutrittskontrolle", "correct": true, "because": "Schützt extern und lokal"}, {"text": "Nur lokale Sicherung", "correct": false, "because": "Risiko bei Schäden"}, {"text": "Ohne Backup", "correct": false, "because": "Gefährlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Tape-Backups veraltet sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Für Langzeitarchivierung geeignet"}, {"text": "Ja", "correct": false, "because": "Immer noch genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode schützt vor Datenverlust durch Ransomware?', 4, '[{"text": "Air-Gapped-Backup", "correct": true, "because": "Isoliert von Netzwerk"}, {"text": "Nur Cloud-Backup", "correct": false, "because": "Angreifbar"}, {"text": "Keine Sicherung", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine vollständige Sicherung immer notwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Kombination mit anderen Typen möglich"}, {"text": "Ja", "correct": false, "because": "Effizienz variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine inkrementelle Sicherung?', 5, '[{"text": "Geringerer Speicherbedarf", "correct": true, "because": "Nur Änderungen"}, {"text": "Schnellere Erstellung", "correct": true, "because": "Weniger Daten"}, {"text": "Einfache Wiederherstellung", "correct": false, "because": "Komplexer"}, {"text": "Bunte Visuals", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer physischen Sicherung unwichtig?', 3, '[{"text": "Zutrittskontrollen", "correct": false, "because": "Schützen Zugang"}, {"text": "Überwachungskameras", "correct": false, "because": "Verhindern Diebstahl"}, {"text": "Raumfarbe", "correct": true, "because": "Kein Sicherungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine Datensicherung plane?', 4, '[{"text": "Häufigkeit, Speicherort, Typ wählen", "correct": true, "because": "Sichert Effizienz"}, {"text": "Nur Vollbackup machen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Riskant"}]');
